<?php require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/db.php';$id=(int)($_GET['id']??0);$p=['title'=>'','category'=>'Web Development','year'=>date('Y'),'description'=>'','cover_image'=>'','project_url'=>'','folder_path'=>'','visual_label'=>'PROJECT','is_featured'=>1];if($id){$q=$pdo->prepare("SELECT * FROM projects WHERE id=?");$q->execute([$id]);$p=$q->fetch()?:$p;}$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$data=[trim($_POST['title']),trim($_POST['category']),trim($_POST['year']),trim($_POST['description']),trim($_POST['cover_image']),trim($_POST['project_url']),trim($_POST['folder_path']),trim($_POST['visual_label']),isset($_POST['is_featured'])?1:0];if($id){$data[]=$id;$q=$pdo->prepare("UPDATE projects SET title=?,category=?,year=?,description=?,cover_image=?,project_url=?,folder_path=?,visual_label=?,is_featured=? WHERE id=?");$q->execute($data);}else{$q=$pdo->prepare("INSERT INTO projects(title,category,year,description,cover_image,project_url,folder_path,visual_label,is_featured) VALUES(?,?,?,?,?,?,?,?,?)");$q->execute($data);}$msg='Project saved.';$id=(int)($id?:$pdo->lastInsertId());$q=$pdo->prepare("SELECT * FROM projects WHERE id=?");$q->execute([$id]);$p=$q->fetch();}function v($p,$k){return htmlspecialchars((string)($p[$k]??''),ENT_QUOTES,'UTF-8');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project editor</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="admin-wrap"><a class="text-link" href="dashboard.php">← Dashboard</a><h1><?= $id?'Edit':'Add'?> <em>project.</em></h1><?php if($msg):?><p class="notice"><?=$msg?></p><?php endif;?><form class="form-card" method="post"><label>Project title *</label><input name="title" required value="<?=v($p,'title')?>"><label>Category</label><input name="category" value="<?=v($p,'category')?>"><label>Year</label><input name="year" value="<?=v($p,'year')?>"><label>Description</label><textarea name="description" rows="5"><?=v($p,'description')?></textarea><label>Cover image path (e.g. assets/images/project.jpg)</label><input name="cover_image" value="<?=v($p,'cover_image')?>"><label>Live website URL (optional)</label><input name="project_url" value="<?=v($p,'project_url')?>"><label>Website folder path (e.g. projects/amora/)</label><input name="folder_path" value="<?=v($p,'folder_path')?>"><label>Visual label</label><input name="visual_label" value="<?=v($p,'visual_label')?>"><label><input type="checkbox" name="is_featured" value="1" <?=$p['is_featured']?'checked':''?> style="width:auto"> Show on homepage</label><button>Save project ↗</button></form></div></body></html>